# Find connected components of 4s using flood fill
def find_components(grid):
    visited = set()
    components = []

    def dfs(r, c):
        stack = [(r, c)]
        comp = []
        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in visited:
                continue
            visited.add((cr, cc))
            comp.append((cr, cc))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 4 and (nr, nc) not in visited:
                    stack.append((nr, nc))
        return comp

    for r in range(R):
        for c in range(C):
            if grid[r][c] == 4 and (r, c) not in visited:
                comp = dfs(r, c)
                if comp:
                    components.append(comp)

    return components

