def flood_fill_from_edge(grid, fill_value):
    """Fill all reachable cells from the grid boundary"""
    R, C = len(grid), len(grid[0])
    visited = [[False]*C for _ in range(R)]

    # Queue of cells to visit (all edge cells)
    queue = []
    for c in range(C):
        if grid[0][c] != fill_value:
            queue.append((0, c))
            visited[0][c] = True
        if grid[R-1][c] != fill_value:
            queue.append((R-1, c))
            visited[R-1][c] = True

    for r in range(1, R-1):
        if grid[r][0] != fill_value:
            queue.append((r, 0))
            visited[r][0] = True
        if grid[r][C-1] != fill_value:
            queue.append((r, C-1))
            visited[r][C-1] = True

    results = set()

    while queue:
        r, c = queue.pop()

        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc

                if 0 <= nr < R and 0 <= nc < C and not visited[nr][nc]:
                    visited[nr][nc] = True

                    # Only traverse through non-fill_value cells
                    if grid[nr][nc] != fill_value:
                        results.add((nr, nc))
                        queue.append((nr, nc))

    return results

